// Создаём промис: new Promise(executor)
const pizzaPromise = new Promise((resolve, reject) => {
  // resolve — вызываем при успехе (пиццу привезли)
  // reject — вызываем при ошибке (кухня закрылась)
  const success = true;
  if (success) {
    resolve("Margherita");  // fulfilled со значением
  } else {
    reject("Kitchen closed");  // rejected с ошибкой
  }
});

// Подписываемся на результат
pizzaPromise
  .then(pizza => console.log("Доставлено:", pizza))  // Margherita
  .catch(err => console.error("Ошибка:", err));

const p = new Promise((resolve, reject) => {
  // Только resolve ИЛИ только reject
  resolve("first");   // этот промис теперь fulfilled
  resolve("second");  // игнорируется — состояние уже set!
});

p.then(val => console.log(val));  // "first" — второе не дойдёт

Promise.resolve(10)
  .then(n => {
    if (n > 5) throw new Error("Too big");  // бросаем ошибку
    return n;
  })
  .then(n => console.log("не выполнится"))  // пропускается
  .catch(err => console.log("Поймал:", err.message));
  // Поймал: Too big

