// Уже выполненный промис
Promise.resolve("done").then(v => console.log(v));  // done

// Уже отклонённый
Promise.reject("fail").catch(e => console.log(e));  // fail

// Загружаем 3 пользователя параллельно
Promise.all([
  fetchUser(1),
  fetchUser(2),
  fetchUser(3)
])
.then(users => {
  console.log(users);  // [u1, u2, u3] — в исходном порядке
})
.catch(err => {
  console.error("Хоть один упал:", err);  // fail fast
});

// Запрос против таймера 5 секунд
const timeout = new Promise((_, reject) =>
  setTimeout(() => reject("Timeout!"), 5000)
);

Promise.race([fetchData(), timeout])
  .then(data => console.log(data))
  .catch(err => console.error(err));  // Timeout! если долго

Promise.allSettled([
  Promise.resolve("ok"),
  Promise.reject("err")
]).then(results => {
  console.log(results[0].status);  // "fulfilled"
  console.log(results[0].value);   // "ok"
  console.log(results[1].status);  // "rejected"
  console.log(results[1].reason);  // "err"
});

// БАГ: промис никогда не завершится
const stuck = new Promise((resolve, reject) => {
  if (false) resolve("ok");
  // нет else → resolve/reject не вызваны → pending forever
});

stuck.then(v => console.log(v));  // никогда не сработает

// ПРАВИЛЬНО: гарантируем завершение
const good = new Promise((resolve, reject) => {
  if (true) resolve("ok");
  else reject("fail");  // есть обе ветки
});

// Колбэк-API → промис
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

delay(1000).then(() => console.log("прошла секунда"));

// Теперь setTimeout работает в цепочке промисов!

// Нельзя: console.log(promise.state) — undefined!
// Только подписка через then/catch:
const p = new Promise(r => r("value"));

p.then(v => {
  console.log(" fulfilled:", v);  // узнаём результат так
});

